insert into source (id, kind, title, origin_uri, storage_key, markdown, ingest_status, ingest_method, word_count, created_at) values
  ('22222222-2222-4222-8222-222222222001', 'pdf', 'FSRS without an A-factor', 'spaces://helloword-seed/fsrs-without-a-factor.pdf', 'seed/fsrs-without-a-factor.pdf', '# FSRS without an A-factor
insert into note (id, title, body_md, body_hash, origin, created_at, updated_at) values
  ('33333333-3333-4333-8333-333333333001', 'FSRS has no A-factor', 'FSRS does not use an ease factor. It estimates retrievability from stability and difficulty, then schedules so retrievability at the next due date matches the retention I asked for.
insert into extract (id, source_id, body_md, priority, selector, anchor_status, suggested_by, accepted, created_at) values
  ('44444444-4444-4444-8444-444444444001', '22222222-2222-4222-8222-222222222001', 'FSRS estimates retrievability from a memory model, not from an ease factor you twist by hand.', 10, '{"exact":"FSRS estimates retrievability from a memory model, not from an ease factor you twist by hand.","prefix":"interval after you press Good.\n\n","suffix":"\n\nThe model tracks two latent va","start":291,"end":384}'::jsonb, 'anchored', 'nemotron', true, '2026-08-06T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444002', '22222222-2222-4222-8222-222222222001', 'The A-factor in SuperMemo is a per-item multiplier on the next interval. FSRS has no equivalent because difficulty and stability are already the model''s explanation of why two cards behave differently.', 15, '{"exact":"The A-factor in SuperMemo is a per-item multiplier on the next interval. FSRS has no equivalent because difficulty and stability are already the model''s explanation of why two cards behave differently.","prefix":"s the retention you asked for.\n\n","suffix":"\n\nThat does not mean you should ","start":700,"end":901}'::jsonb, 'anchored', 'human', true, '2026-08-07T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444003', '22222222-2222-4222-8222-222222222001', 'If you compress wall-clock time without compressing the unit of a day, FSRS concludes you recalled the card far too early and inflates stability.', 20, '{"exact":"If you compress wall-clock time without compressing the unit of a day, FSRS concludes you recalled the card far too early and inflates stability.","prefix":"own so cards return in seconds. ","suffix":" The diagnostics screen then sho","start":1600,"end":1745}'::jsonb, 'anchored', 'nemotron', true, '2026-08-08T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444004', '22222222-2222-4222-8222-222222222001', 'Raising request_retention from 0.90 to 0.95 is the principled way to see cards more often. It shortens every interval because the model is targeting a higher chance of recall.', 18, '{"exact":"Raising request_retention from 0.90 to 0.95 is the principled way to see cards more often. It shortens every interval because the model is targeting a higher chance of recall.","prefix":"n is the other legitimate knob. ","suffix":"\n\nDemo mode is where teams usual","start":1306,"end":1481}'::jsonb, 'anchored', 'nemotron', true, '2026-08-09T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444005', '22222222-2222-4222-8222-222222222002', 'A reading pile is a graveyard. A reading queue is a promise that the next thing you see is the most important unread span you have.', 12, '{"exact":"A reading pile is a graveyard. A reading queue is a promise that the next thing you see is the most important unread span you have.","prefix":" next item. It only has guilt.\n\n","suffix":"\n\nPriority is not importance in ","start":198,"end":329}'::jsonb, 'anchored', 'human', true, '2026-08-10T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444006', '22222222-2222-4222-8222-222222222002', 'Priority is not importance in the abstract. It is a ranking of what should surface next, on a 0-100 scale where lower numbers float to the top.', 22, '{"exact":"Priority is not importance in the abstract. It is a ranking of what should surface next, on a 0-100 scale where lower numbers float to the top.","prefix":"mportant unread span you have.\n\n","suffix":"\n\nThe unit of work is not the do","start":331,"end":474}'::jsonb, 'anchored', 'nemotron', true, '2026-08-11T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444007', '22222222-2222-4222-8222-222222222002', 'Extracts are not notes. An extract is a span you might want to remember; a note is the sentence you would say if you had to explain it tomorrow.', 8, '{"exact":"Extracts are not notes. An extract is a span you might want to remember; a note is the sentence you would say if you had to explain it tomorrow.","prefix":"s at the priority you left it.\n\n","suffix":"\n\nThat distinction is the whole ","start":704,"end":848}'::jsonb, 'anchored', 'human', true, '2026-08-12T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444008', '22222222-2222-4222-8222-222222222002', 'When the source moves, the highlight should try to find itself again: exact quote, then prefix and suffix, then fuzzy. If all three fail, it is orphaned, not deleted.', 25, '{"exact":"When the source moves, the highlight should try to find itself again: exact quote, then prefix and suffix, then fuzzy. If all three fail, it is orphaned, not deleted.","prefix":"ets in the normalized markdown. ","suffix":"\n\nOrphans are not a failure of t","start":1280,"end":1446}'::jsonb, 'anchored', 'nemotron', true, '2026-08-13T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444009', '22222222-2222-4222-8222-222222222003', 'Nothing generates an activity directly from a source. The note is always in the path, so the user''s own words are what gets tested.', 5, '{"exact":"Nothing generates an activity directly from a source. The note is always in the path, so the user''s own words are what gets tested.","prefix":"y place the human is required.\n\n","suffix":"\n\nThis is also the answer to \"is","start":181,"end":312}'::jsonb, 'anchored', 'human', true, '2026-08-14T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444010', '22222222-2222-4222-8222-222222222003', 'AI may draft a note from extracts, but the draft is a suggestion that sits in an editor. Committing it without a human pass is how you end up reviewing someone else''s sentences.', 14, '{"exact":"AI may draft a note from extracts, but the draft is a suggestion that sits in an editor. Committing it without a human pass is how you end up reviewing someone else''s sentences.","prefix":"ts an artifact you can rewrite. ","suffix":"\n\nThe edit is visible. Origin is","start":452,"end":629}'::jsonb, 'anchored', 'nemotron', true, '2026-08-15T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444011', '22222222-2222-4222-8222-222222222003', 'When the note changes, downstream activities become stale. Regeneration is an offer, not a silent rewrite.', 16, '{"exact":"When the note changes, downstream activities become stale. Regeneration is an offer, not a silent rewrite.","prefix":"ery activity generated from it. ","suffix":"\n\nStale does not mean wrong. It ","start":777,"end":883}'::jsonb, 'anchored', 'nemotron', true, '2026-08-16T16:00:00.000Z'::timestamptz),
  ('44444444-4444-4444-8444-444444444012', '22222222-2222-4222-8222-222222222003', 'The product is the edit. If you cannot point at a paragraph the user rewrote before they were quizzed on it, you have built a chatbot with extra steps.', 6, '{"exact":"The product is the edit. If you cannot point at a paragraph the user rewrote before they were quizzed on it, you have built a chatbot with extra steps.","prefix":" it is untouched, not unknown.\n\n","suffix":"\n\nKeep the original PDF if you w","start":1315,"end":1466}'::jsonb, 'anchored', 'human', true, '2026-08-17T16:00:00.000Z'::timestamptz);
