  ('55555555-5555-4555-8555-555555555001', '33333333-3333-4333-8333-333333333001', 'mcq', '{"type":"mcq","stem":"What does FSRS estimate retrievability from?","options":["An ease factor the user twists","A memory model of stability and difficulty","The number of times you pressed Easy","The length of the note"],"answer":1,"explanation":"FSRS is a memory model, not an ease slider."}'::jsonb, '71d4ee0cf652e18221b942a1e7dba9862c8008ef825e9f735ecf9f98004fd300', NULL, '2026-09-04T16:00:00.000Z'::timestamptz),
  ('55555555-5555-4555-8555-555555555002', '33333333-3333-4333-8333-333333333001', 'mcq', '{"type":"mcq","stem":"Which SuperMemo idea does FSRS refuse to put inside the model?","options":["Priority","The A-factor","Mercy postpone","Extracts"],"answer":1}'::jsonb, '71d4ee0cf652e18221b942a1e7dba9862c8008ef825e9f735ecf9f98004fd300', NULL, '2026-09-05T16:00:00.000Z'::timestamptz),
