  ('55555555-5555-4555-8555-555555555004', '33333333-3333-4333-8333-333333333003', 'mcq', '{"type":"mcq","stem":"Raising request_retention from 0.90 to 0.95 will:","options":["Lengthen every interval","Shorten every interval","Change only new cards","Disable fuzz"],"answer":1}'::jsonb, '12d7aa52e08d3ae0ba6d4eea918c3e7f95a9a9dfb0ed28731b7c1a4359d61600', NULL, '2026-09-07T16:00:00.000Z'::timestamptz),
  ('55555555-5555-4555-8555-555555555005', '33333333-3333-4333-8333-333333333004', 'mcq', '{"type":"mcq","stem":"Why is multiplying intervals down a bad demo trick?","options":["It looks slow on stage","FSRS thinks you recalled too early and inflates stability","ts-fsrs cannot handle seconds","Judges prefer Anki"],"answer":1}'::jsonb, 'd5e3f3f4c1dcc9c48c872f81c5fac6be2b254566ea8a34571c05ec04c6bd1c0a', NULL, '2026-09-08T16:00:00.000Z'::timestamptz),
  ('55555555-5555-4555-8555-555555555006', '33333333-3333-4333-8333-333333333005', 'mcq', '{"type":"mcq","stem":"What is the difference between a pile and a queue?","options":["A pile is stored in Spaces","A queue has a next item; a pile does not","A pile is markdown","A queue cannot contain PDFs"],"answer":1}'::jsonb, '2e704e44e900309a3bc13fe7ee880d0f252899c4b17569f6b689c5c3b68ca07a', NULL, '2026-09-09T16:00:00.000Z'::timestamptz),
